begin;
create extension if not exists pgtap with schema extensions;
select plan(23);
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select set_config('request.jwt.claims','{"aal":"aal1"}',true);
select throws_ok($$insert into public.hermes_connections(company_id,agency_owner_id,address,profile,key_encrypted,state) values ('10000000-0000-0000-0000-000000000001',auth.uid(),'http://localhost','writer','ciphertext','connected')$$,'42501',null,'Agency management requires two-step verification');
select set_config('request.jwt.claims','{"aal":"aal2"}',true);
select lives_ok($$insert into public.hermes_connections(id,company_id,agency_owner_id,address,profile,key_encrypted,state) values ('c0000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000001',auth.uid(),'http://localhost','writer','ciphertext','connected')$$,'verified Agency owner connects');
select is((select count(id)::int from public.hermes_connections),1,'Agency owner reads their Connection');
select throws_ok($$select key_encrypted from public.hermes_connections$$,'42501',null,'even the Agency owner cannot read ciphertext');
select lives_ok($$update public.hermes_connections set key_encrypted='replacement' where id='c0000000-0000-0000-0000-000000000001'$$,'Agency owner replaces the key');
select throws_ok($$update public.hermes_connections set agency_owner_id='20000000-0000-0000-0000-000000000002'$$,'42501',null,'ownership cannot be reassigned');
reset role;
update public.members set role='owner' where company_id='10000000-0000-0000-0000-000000000001' and person_id='20000000-0000-0000-0000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select state from public.hermes_connections),'connected','company Owner sees state');
select throws_ok($$select key_encrypted from public.hermes_connections$$,'42501',null,'company Owner cannot read ciphertext');
select throws_ok($$insert into public.hermes_connections(company_id,agency_owner_id,address,profile,key_encrypted,state) values ('10000000-0000-0000-0000-000000000001',auth.uid(),'http://localhost','writer','ciphertext','connected')$$,'42501',null,'company Owner cannot connect');
with changed as (update public.hermes_connections set key_encrypted='forbidden' returning id) select is((select count(*)::int from changed),0,'company Owner cannot replace');
with removed as (delete from public.hermes_connections returning id) select is((select count(*)::int from removed),0,'company Owner cannot remove');
reset role;
update public.members set role='manager' where company_id='10000000-0000-0000-0000-000000000001' and person_id='20000000-0000-0000-0000-000000000002';
set local role authenticated;
select is((select count(id)::int from public.hermes_connections),0,'Manager cannot read Connections');
select set_config('request.jwt.claim.sub','30000000-0000-0000-0000-000000000001',true);
select is((select count(id)::int from public.hermes_connections),0,'Contributor cannot read Connections');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000003',true);
select is((select count(id)::int from public.hermes_connections),0,'Reviewer cannot read Connections');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000004',true);
select is((select count(id)::int from public.hermes_connections),0,'Viewer cannot read Connections');
reset role;
update public.people set agency_owner=true where id='20000000-0000-0000-0000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select is((select count(id)::int from public.hermes_connections),0,'another Agency sees no Connection despite agency-wide access');
with changed as (update public.hermes_connections set key_encrypted='forbidden' returning id) select is((select count(*)::int from changed),0,'another Agency cannot replace');
with removed as (delete from public.hermes_connections returning id) select is((select count(*)::int from removed),0,'another Agency cannot remove');
select throws_ok($$insert into public.hermes_connections(company_id,agency_owner_id,address,profile,key_encrypted,state) values ('10000000-0000-0000-0000-000000000001','20000000-0000-0000-0000-000000000001','http://localhost','writer','ciphertext','connected')$$,'42501',null,'another Agency cannot create as this owner');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
with removed as (delete from public.hermes_connections returning id) select is((select count(*)::int from removed),1,'owning Agency removes the Connection');
set local role anon;
select throws_ok($$select id from public.hermes_connections$$,'42501',null,'anonymous callers cannot read');
reset role;
select ok(not has_column_privilege('authenticated','public.hermes_connections','company_id','update'),'company cannot be changed');
select ok((select relrowsecurity from pg_class where oid='public.hermes_connections'::regclass),'RLS protects Connections');
select * from finish();
rollback;
